from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaObject, SchemaField


class OperationStatusResponseV1(SchemaObject):
    id = SchemaField(name="id")
    result = SchemaField(name="result")
    type = SchemaField(name="type")

    def __init__(self, id, result, type):
        self.type = type
        self.result = result
        self.id = id

        super(OperationStatusResponseV1, self).__init__()
